<style lang="scss" src="./list.scss"></style>

<script>
import get from "lodash/get";
import { matchSorter } from "match-sorter";
import { Component, Prop, Vue } from "vue-property-decorator";
import { DynamicScroller, DynamicScrollerItem } from "vue-virtual-scroller";
import { IconShape } from "../../icon/icon.constants";
import Icon from "../../icon/icon.vue";
import "vue-virtual-scroller/dist/vue-virtual-scroller.css";

const ITEM_HEIGHT = 55;
const SCROLLER_PADDING_Y = 4;
const EXTRA_ITEM_PEEK = 26;

/**
 * This is an uncontrolled list component (only renders a list of items).
 * The value of the clicked choice is emitted via the `click` event.
 * Choices are rendered as 'selected' via the 'value' prop.
 */
@Component({
  components: {
    DynamicScroller,
    DynamicScrollerItem,
    Icon,
  },
})
export default class List extends Vue {
  /**
   * The choices a user can choose from.
   * e.g.
   * [
   *  { label: "Choice 1", value: 1 },
   *  { label: "Choice 2", value: 2 },
   *  { label: "Choice 3", value: 3 },
   * ]
   */
  @Prop({
    type: Array,
    default: () => [],
  })
  items;

  /**
   * The currently selected value(s).
   */
  @Prop({
    type: [Number, String, Array, Boolean],
    required: false,
  })
  value;

  /**
   * Enables the search functionality.
   */
  @Prop({
    type: Boolean,
    default: false,
  })
  search;

  @Prop({
    type: Function,
    default: () => () => {},
  })
  itemStyle;

  // ENUMS
  IconShape = IconShape;

  // DATA
  searchValue = "";

  /**
   * Returns the items that are matched via the search bar
   */
  get itemsBySearch() {
    return matchSorter(this.items, this.searchValue, {
      keys: ["label", "value"],
    });
  }

  /**
   * Returns items along with a corresponding 'selected' value to render the
   * selected values
   */
  get itemsWithSelectedValues() {
    const items =
      this.search && this.searchValue ? this.itemsBySearch : this.items;

    return items.map((item) => ({
      ...item,
      selected: Array.isArray(this.value)
        ? this.value.includes(item.value)
        : item.value === this.value,
    }));
  }

  get get() {
    return get;
  }

  get scrollerHeight() {
    const numItems = this.itemsWithSelectedValues.length;
    const height =
      numItems < 5
        ? "auto"
        : `${4 * ITEM_HEIGHT + SCROLLER_PADDING_Y + EXTRA_ITEM_PEEK}px`;
    return height;
  }

  getMenuItemStyles(item) {
    const itemStyle = this.itemStyle(item);
    return {
      // left indicator
      "--indicator-color": get(itemStyle, "indicator"),

      // background color
      "--menu-item-bg--normal": get(itemStyle, "background.normal"),
      "--menu-item-bg--hover": get(itemStyle, "background.hover"),
      "--menu-item-bg--active": get(itemStyle, "background.active"),
      "--menu-item-bg-selected--normal": get(
        itemStyle,
        "background.selected.normal"
      ),
      "--menu-item-bg-selected--hover": get(
        itemStyle,
        "background.selected.hover"
      ),
      "--menu-item-bg-selected--active": get(
        itemStyle,
        "background.selected.active"
      ),

      // text color
      "--menu-item-text--normal": get(itemStyle, "text.normal"),
      "--menu-item-text--hover": get(itemStyle, "text.hover"),
      "--menu-item-text--active": get(itemStyle, "text.active"),
      "--menu-item-text-selected--normal": get(
        itemStyle,
        "text.selected.normal"
      ),
      "--menu-item-text-selected--hover": get(itemStyle, "text.selected.hover"),
      "--menu-item-text-selected--active": get(
        itemStyle,
        "text.selected.active"
      ),
    };
  }
}
</script>

<template>
  <div :class="['List', { 'List--WithSearch': this.search }]">
    <div v-if="search" class="List__SearchContainerBackdrop" />
    <div v-if="search" class="List__SearchContainer">
      <input
        class="List__SearchInput"
        v-model="searchValue"
        type="text"
        placeholder="Search"
      />
      <Icon
        class="List__SearchIcon"
        :shape="IconShape.SEARCH"
        :size="20"
        :color="'#000'"
      />
    </div>
    <div
      v-if="itemsWithSelectedValues.length === 0"
      class="List__Scroller List__Scroller--Empty"
    >
      No results match.
    </div>
    <DynamicScroller
      v-else
      role="listbox"
      class="List__Scroller"
      key-field="value"
      :items="itemsWithSelectedValues"
      :min-item-size="11"
      :style="{ height: scrollerHeight }"
      :buffer="400"
    >
      <template v-slot="{ item, index, active }">
        <DynamicScrollerItem
          :class="'List__ScrollerItem'"
          :item="item"
          :active="active"
          :size-dependencies="[item.label]"
          :data-index="index"
          role="option"
        >
          <div class="List__MenuItemContainer">
            <div
              @click="$emit('click', item.value, item)"
              :class="[
                'List__MenuItem',
                {
                  'List__MenuItem--selected': item.selected,
                },
              ]"
              :style="getMenuItemStyles(item)"
            >
              <!-- FRONT ICON -->
              <div
                v-if="get(itemStyle(item), 'iconStart.show')"
                class="List__MenuItemIcon List__MenuItemIcon--Start"
              >
                <Icon
                  v-bind="{
                    size: 20,
                    ...get(itemStyle(item), 'iconStart.iconProps'),
                  }"
                />
              </div>

              <!-- ITEM TEXT -->
              <span
                :class="[
                  'List__MenuItemText',
                  {
                    'List__MenuItemText--WithIconStart': get(
                      itemStyle(item),
                      'iconStart.show'
                    ),
                  },
                ]"
              >
                {{ item.label }}
              </span>

              <!-- BACK ICON -->
              <div
                v-if="get(itemStyle(item), 'iconEnd.show')"
                class="List__MenuItemIcon List__MenuItemIcon--End"
              >
                <Icon
                  v-bind="{
                    size: 20,
                    ...get(itemStyle(item), 'iconEnd.iconProps'),
                  }"
                />
              </div>
            </div>
          </div>
        </DynamicScrollerItem>
      </template>
    </DynamicScroller>
  </div>
</template>
